-- Shared staff contract v1 fixture: IDs are generated by the local runner.
SELECT set_config('fixture.a', :'business_a', false),set_config('fixture.b', :'business_b', false);
SELECT set_config('fixture.platformOnly', :'user_platformOnly', false);
SELECT set_config('fixture.platformMember', :'user_platformMember', false);
SELECT set_config('fixture.ownerA', :'user_ownerA', false);
SELECT set_config('fixture.managerA', :'user_managerA', false);
SELECT set_config('fixture.staffA', :'user_staffA', false);
SELECT set_config('fixture.inactiveA', :'user_inactiveA', false);
SELECT set_config('fixture.staffB', :'user_staffB', false);
SELECT set_config('fixture.legacyOnly', :'user_legacyOnly', false);
SELECT set_config('fixture.inactivePlatform', :'user_inactivePlatform', false);
INSERT INTO auth.users SELECT current_setting('fixture.'||n)::uuid FROM unnest(ARRAY['platformOnly','platformMember','ownerA','managerA','staffA','inactiveA','staffB','legacyOnly','inactivePlatform']) n;
INSERT INTO core.businesses VALUES (current_setting('fixture.a')::uuid),(current_setting('fixture.b')::uuid);
INSERT INTO core.crm_staff VALUES (current_setting('fixture.legacyOnly')::uuid,true);
INSERT INTO core.business_staff(business_id,staff_id,role,active)
 SELECT current_setting('fixture.a')::uuid,current_setting('fixture.'||n)::uuid,r,enabled FROM (VALUES('ownerA','owner',true),('managerA','manager',true),('staffA','staff',true),('inactiveA','staff',false),('platformMember','staff',true)) v(n,r,enabled);
INSERT INTO core.business_staff VALUES(current_setting('fixture.b')::uuid,current_setting('fixture.staffB')::uuid,'staff',true);
INSERT INTO core.platform_operators SELECT current_setting('fixture.'||n)::uuid,enabled FROM (VALUES('platformOnly',true),('platformMember',true),('inactivePlatform',false)) v(n,enabled);
INSERT INTO core.ops_write_settings VALUES (current_setting('fixture.a')::uuid,false),(current_setting('fixture.b')::uuid,false);
CREATE FUNCTION pg_temp.login(who uuid) RETURNS void LANGUAGE plpgsql AS $$ BEGIN
 PERFORM set_config('request.jwt.claim.sub',coalesce(who::text,''),false);
 PERFORM set_config('request.jwt.claim.role','authenticated',false);
END; $$;
CREATE FUNCTION pg_temp.expect_error(statement text,expected text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN
 BEGIN EXECUTE statement; EXCEPTION WHEN OTHERS THEN IF SQLSTATE=expected THEN RETURN; ELSE RAISE; END IF; END;
 RAISE EXCEPTION 'Expected SQLSTATE %',expected;
END; $$;
DO $$
DECLARE b uuid:=current_setting('fixture.a')::uuid; other uuid:=current_setting('fixture.b')::uuid;
 u uuid:=current_setting('fixture.ownerA')::uuid; t uuid:=gen_random_uuid(); h text:=repeat('a',64); r jsonb; c jsonb; action uuid; n text;
BEGIN
 -- Every member role and the platform+member path can write without crm_staff.
 FOREACH n IN ARRAY ARRAY['ownerA','managerA','staffA','platformMember'] LOOP
  PERFORM pg_temp.login(current_setting('fixture.'||n)::uuid);
  ASSERT core.staff_authorized_v1(b,'ops.write') IS TRUE;
  r:=public.ops_write_preview(b,t,h,gen_random_uuid());ASSERT r->>'status'='previewed';
  PERFORM pg_temp.expect_error(format('SELECT public.ops_write_preview(%L,%L,%L,%L)',other,t,h,gen_random_uuid()),'42501');
 END LOOP;
 FOREACH n IN ARRAY ARRAY['platformOnly','inactiveA','inactivePlatform','legacyOnly','staffB'] LOOP
  PERFORM pg_temp.login(current_setting('fixture.'||n)::uuid);
  ASSERT core.staff_authorized_v1(b,'ops.write') IS FALSE;
  PERFORM pg_temp.expect_error(format('SELECT public.ops_write_preview(%L,%L,%L,%L)',b,t,h,gen_random_uuid()),'42501');
 END LOOP;
 PERFORM pg_temp.login(current_setting('fixture.platformOnly')::uuid);
 ASSERT core.staff_authorized_v1(b,'ops.read') IS TRUE;
 ASSERT core.staff_authorized_v1(NULL,'platform.read') IS TRUE;
 ASSERT core.staff_authorized_v1(NULL,'ops.write') IS FALSE;
 ASSERT core.staff_authorized_v1(gen_random_uuid(),'ops.read') IS FALSE;
 ASSERT core.staff_authorized_v1(b,'unknown.operation') IS FALSE;
 PERFORM pg_temp.login(current_setting('fixture.inactivePlatform')::uuid);
 ASSERT core.staff_authorized_v1(b,'ops.read') IS FALSE;
 PERFORM pg_temp.login(NULL);ASSERT core.staff_authorized_v1(b,'ops.write') IS FALSE;
 PERFORM pg_temp.login(u);ASSERT core.staff_authorized_v1(NULL,'platform.read') IS FALSE;
 r:=public.ops_write_preview(b,t,h,gen_random_uuid());action:=(r->>'id')::uuid;
 ASSERT public.ops_write_preview(b,t,h,(r->>'idempotency_key')::uuid)->>'id'=action::text;
 PERFORM pg_temp.expect_error(format('SELECT public.ops_write_preview(%L,%L,%L,%L)',b,t,repeat('b',64),r->>'idempotency_key'),'22023');
 r:=public.ops_write_approve(b,action,t,h);ASSERT r->>'status'='approved';
 PERFORM pg_temp.expect_error(format('SELECT public.ops_write_claim(%L,%L,%L,%L,%L)',b,action,u,gen_random_uuid(),h),'22023');
 PERFORM pg_temp.expect_error(format('SELECT public.ops_write_claim(%L,%L,%L,%L,%L)',b,action,u,t,repeat('b',64)),'22023');
 -- Claimed actor is never inferred from an arbitrary p_staff_id.
 PERFORM pg_temp.expect_error(format('SELECT public.ops_write_claim(%L,%L,%L,%L,%L)',b,action,current_setting('fixture.staffB'),t,h),'42501');
 PERFORM pg_temp.login(NULL);PERFORM set_config('request.jwt.claim.role','service_role',false);
 PERFORM pg_temp.expect_error(format('SELECT public.ops_write_claim(%L,%L,%L,%L,%L)',b,action,u,t,h),'42501');
 PERFORM set_config('request.jwt.claim.sub',u::text,false);
 PERFORM pg_temp.expect_error(format('SELECT public.ops_write_claim(%L,%L,%L,%L,%L)',b,action,u,t,h),'42501');
 PERFORM pg_temp.login(u);
 c:=public.ops_write_claim(b,action,u,t,h);ASSERT c->>'status'='executing';
 ASSERT public.ops_write_claim(b,action,u,t,h) IS NULL;
 PERFORM pg_temp.expect_error(format('SELECT public.ops_write_finalize(%L,%L,%L,%L,true)',b,action,current_setting('fixture.staffB'),c->>'claim_token'),'42501');
 PERFORM pg_temp.login(NULL);PERFORM set_config('request.jwt.claim.role','service_role',false);
 PERFORM pg_temp.expect_error(format('SELECT public.ops_write_finalize(%L,%L,%L,%L,true)',b,action,u,c->>'claim_token'),'42501');
 PERFORM pg_temp.login(u);
 ASSERT public.ops_write_finalize(b,action,u,gen_random_uuid(),true) IS NULL;
 r:=public.ops_write_finalize(b,action,u,(c->>'claim_token')::uuid,true);ASSERT r->>'status'='succeeded';ASSERT NOT r?'claim_token';
 ASSERT public.ops_write_finalize(b,action,u,(c->>'claim_token')::uuid,true) IS NULL;
 ASSERT public.ops_write_approve(b,action,t,h)->>'status'='succeeded';
 -- Expiration cannot be renewed and executing actions cannot be reclaimed.
 r:=public.ops_write_preview(b,t,h,gen_random_uuid());action:=(r->>'id')::uuid;
 UPDATE core.ops_write_actions SET created_at=clock_timestamp()-interval '10 minutes',expires_at=clock_timestamp()-interval '1 minute' WHERE business_id=b AND id=action;
 ASSERT public.ops_write_approve(b,action,t,h)->>'status'='expired';
 r:=public.ops_write_preview(b,t,h,gen_random_uuid());action:=(r->>'id')::uuid;PERFORM public.ops_write_approve(b,action,t,h);
 UPDATE core.ops_write_actions SET created_at=clock_timestamp()-interval '10 minutes',expires_at=clock_timestamp()-interval '1 minute' WHERE business_id=b AND id=action;
 ASSERT public.ops_write_claim(b,action,u,t,h) IS NULL;
 ASSERT public.ops_write_status(b,action)->>'status'='expired';
 r:=public.ops_write_preview(b,t,h,gen_random_uuid());action:=(r->>'id')::uuid;PERFORM public.ops_write_approve(b,action,t,h);
 UPDATE core.ops_write_settings SET kill_switch=true WHERE business_id=b;
 PERFORM pg_temp.expect_error(format('SELECT public.ops_write_claim(%L,%L,%L,%L,%L)',b,action,u,t,h),'55000');
 UPDATE core.ops_write_settings SET kill_switch=false WHERE business_id=b;
 c:=public.ops_write_claim(b,action,u,t,h);UPDATE core.ops_write_settings SET kill_switch=true WHERE business_id=b;
 r:=public.ops_write_finalize(b,action,u,(c->>'claim_token')::uuid,true);ASSERT r->>'safe_result_code'='disabled';ASSERT r->>'status'='failed';
 UPDATE core.ops_write_settings SET kill_switch=false WHERE business_id=b;
 -- Persisted approval belongs to the approving user, not another member.
 r:=public.ops_write_preview(b,t,h,gen_random_uuid());action:=(r->>'id')::uuid;PERFORM public.ops_write_approve(b,action,t,h);
 PERFORM pg_temp.login(current_setting('fixture.managerA')::uuid);
 PERFORM pg_temp.expect_error(format('SELECT public.ops_write_execute_dry_run(%L,%L,%L,%L)',b,action,t,h),'42501');
 PERFORM pg_temp.login(u);
 r:=public.ops_write_execute_dry_run(b,action,t,h);ASSERT r->>'status'='succeeded';ASSERT NOT r?'claim_token';
 ASSERT public.ops_write_execute_dry_run(b,action,t,h) IS NULL;
 PERFORM pg_temp.login(current_setting('fixture.staffB')::uuid);
 PERFORM pg_temp.expect_error(format('SELECT public.ops_write_status(%L,%L)',b,action),'42501');
 r:=public.ops_write_preview(other,t,h,gen_random_uuid());ASSERT r->>'business_id'=other::text;
 -- Composite FK cannot bind actor B into a tenant A audit row.
 PERFORM pg_temp.expect_error(format('INSERT INTO core.ops_write_actions(business_id,action_type,target_id,preview_hash,created_by,idempotency_key) VALUES(%L,%L,%L,%L,%L,%L)',b,'dry_run',t,h,current_setting('fixture.staffB'),gen_random_uuid()),'23503');
 ASSERT NOT has_table_privilege('authenticated','core.ops_write_actions','INSERT');
 ASSERT NOT has_table_privilege('service_role','core.ops_write_actions','UPDATE');
 ASSERT NOT has_table_privilege('authenticated','core.business_staff','SELECT');
 ASSERT NOT has_table_privilege('service_role','core.platform_operators','SELECT');
 ASSERT NOT has_function_privilege('authenticated','core.staff_authorized_v1(uuid,text)','EXECUTE');
 ASSERT NOT has_function_privilege('authenticated','public.ops_write_claim(uuid,uuid,uuid,uuid,text)','EXECUTE');
 ASSERT NOT has_function_privilege('anon','public.ops_write_preview(uuid,uuid,text,uuid)','EXECUTE');
 ASSERT has_function_privilege('authenticated','public.ops_write_execute_dry_run(uuid,uuid,uuid,text)','EXECUTE');
 ASSERT has_function_privilege('service_role','public.ops_write_finalize(uuid,uuid,uuid,uuid,boolean)','EXECUTE');
END; $$;
SELECT set_config('request.jwt.claim.sub', :'user_ownerA', false),set_config('request.jwt.claim.role','authenticated',false);
SET ROLE authenticated;
SELECT public.ops_write_preview(:'business_a',gen_random_uuid(),repeat('a',64),gen_random_uuid());
RESET ROLE;
